class ScriptNameMiddleware:
    """WSGI middleware: `environ` is the per-request WSGI dict, not the process environment."""

    def __init__(self, wsgi_app):
        self.wsgi_app = wsgi_app

    def __call__(self, environ, start_response):
        environ["SCRIPT_NAME"] = environ.get("HTTP_X_SCRIPT_NAME", "")
        return self.wsgi_app(environ, start_response)


app.wsgi_app = ScriptNameMiddleware(app.wsgi_app)


@app.route("/status")
def status():
    child_env = dict(os.environ)
    child_env["REQUEST_TAG"] = request.args.get("tag", "")
    merged = {**os.environ, "OTHER": request.args.get("o", "")}
    os.system("ls -la")
    rev = subprocess.getoutput("git rev-parse HEAD")
    return {"rev": rev, "n": len(child_env) + len(merged)}

