import sqlalchemy


def copy_table(src_db, dest_db, table, condition=None):
    query = table.select()
    if condition is not None:
        query = query.where(condition)
    rows = src_db.execute(query)
    for row in rows:
        dest_db.execute(table.insert(), dict(row))


def run(src_url, dest_url, tables):
    src = sqlalchemy.create_engine(src_url).connect()
    dest = sqlalchemy.create_engine(dest_url).connect()
    for t in tables:
        copy_table(src, dest, t)

