"""C1 twins: SAFE SQL built from provably constant values. Each is a public method of an
importable package, the shape that makes Skylos's SQL tracer return `unknown`."""
import sqlite3

TABLE = "users"
ORDER = {"asc": "ASC", "desc": "DESC"}


class Store:
    def __init__(self, path):
        self.conn = sqlite3.connect(path)

    def by_ids(self, ids):
        # SAFE: only "?" placeholders are interpolated
        q = "SELECT * FROM users WHERE id IN (%s)" % ",".join("?" for _ in ids)
        return self.conn.execute(q, list(ids)).fetchall()

    def sorted_users(self, desc):
        # SAFE: IfExp over two literals (dead-branch / join of Exact values)
        order = "DESC" if desc else "ASC"
        return self.conn.execute(f"SELECT * FROM users ORDER BY name {order}").fetchall()

    def sorted_users_map(self, key):
        # SAFE: constant-key container lookup with a literal default
        order = ORDER.get(key, "ASC")
        return self.conn.execute(f"SELECT * FROM users ORDER BY name {order}").fetchall()

    def count(self):
        # SAFE: module-level constant bound once
        return self.conn.execute(f"SELECT COUNT(*) FROM {TABLE}").fetchone()

    def _count_table(self, table):
        # SAFE: every caller passes a literal (interprocedural constant)
        return self.conn.execute("SELECT COUNT(*) FROM %s" % table).fetchone()

    def stats(self):
        return self._count_table("users"), self._count_table("posts")

    def set_version(self, ver):
        # SAFE: %d formatting of an int
        self.conn.execute("PRAGMA user_version = %d" % (ver,))

    def export(self, extra_table):
        # NOT constant: the literal list is mutated before the loop; C1's must-literal
        # refutation only looks at Name bindings and would call `t` literal
        tables = ["users", "posts"]
        tables.append(extra_table)
        for t in tables:
            self.conn.execute(f"SELECT * FROM {t}")

